import{_ as a,o as r,c as t,ae as i}from"./chunks/framework.DBosx3SP.js";const m=JSON.parse('{"title":"Primitives","description":"","frontmatter":{},"headers":[],"relativePath":"rendering/primitives.md","filePath":"rendering/primitives.md","lastUpdated":1792996843000}'),s={name:"rendering/primitives.md"};function o(n,e,l,d,h,c){return r(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="primitives" tabindex="-1">Primitives <a class="header-anchor" href="#primitives" aria-label="Permalink to &quot;Primitives&quot;">​</a></h1><p>Plot -&gt; Geometry -&gt; Primitive</p><p>Each primitive has dedicated GPU renderer type, vertex shader and frag shader.</p><h2 id="primitives-1" tabindex="-1">Primitives <a class="header-anchor" href="#primitives-1" aria-label="Permalink to &quot;Primitives&quot;">​</a></h2><ul><li>To draw UI as primitives, we can convert PlotId to GeometryId. (Merge plot id counter with geometry id counter, and add <code>pub(crate) fn as_geometry_id()</code>.)</li><li>For SOA, you will want MarkerBatch instead of <code>Vec&lt;Marker&gt;</code>, holds various Series (and possibly clipping scissor).</li></ul><h2 id="todo" tabindex="-1">TODO <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;TODO&quot;">​</a></h2><h3 id="minimizing-the-shader-switches-vs-scissor-rect" tabindex="-1">Minimizing the shader switches / VS / Scissor rect <a class="header-anchor" href="#minimizing-the-shader-switches-vs-scissor-rect" aria-label="Permalink to &quot;Minimizing the shader switches / VS / Scissor rect&quot;">​</a></h3><p>To minimize the number of shader program switches, we should aggregate the primitives from all PlotInstance, and then draw each primitive type at once.<br> However each PlotInstance has its own scissor rect, which can be set to one <code>RenderPass</code>.</p><p>Todo: check if all primitives types can implement the clipping (rect bbox / polars area) in frag shader.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct AggregatedPrimitiveSet {</span></span>
<span class="line"><span>  texts: HashMap&lt;GeometryInstanceId, Vec&lt;Text&gt;&gt;, // We maintain multiple Vec&lt;&gt;, so each Vec can be incrementally updated.</span></span>
<span class="line"><span>  bands: HashMap&lt;GeometryId, Vec&lt;Band&gt;&gt;,</span></span>
<span class="line"><span>  markers: HashMap&lt;GeometryId, Vec&lt;Marker&gt;&gt;,</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="primitiveset-has-vec-marker-instead-of-marker-and-marker-is-already-soas" tabindex="-1">PrimitiveSet has <code>Vec&lt;Marker&gt;</code> instead of Marker, and Marker is already SOAs <a class="header-anchor" href="#primitiveset-has-vec-marker-instead-of-marker-and-marker-is-already-soas" aria-label="Permalink to &quot;PrimitiveSet has \`Vec&lt;Marker&gt;\` instead of Marker, and Marker is already SOAs&quot;">​</a></h3><ul><li>FacetGeometry needs multiple Marker.</li><li>Even without FacetGeometry, Band/Violin draws multiple curves.</li></ul><h3 id="per-point-attributes" tabindex="-1">Per-point attributes <a class="header-anchor" href="#per-point-attributes" aria-label="Permalink to &quot;Per-point attributes&quot;">​</a></h3><p>[table describing each attribute]<br> e.g. color / <code>ColorSeries</code> / packed RGBA</p><h3 id="uniform" tabindex="-1">Uniform <a class="header-anchor" href="#uniform" aria-label="Permalink to &quot;Uniform&quot;">​</a></h3><p>window_size<br> transform<br> scale_uniforms</p><h2 id="marker-3d" tabindex="-1">Marker 3D <a class="header-anchor" href="#marker-3d" aria-label="Permalink to &quot;Marker 3D&quot;">​</a></h2><h2 id="line" tabindex="-1">Line <a class="header-anchor" href="#line" aria-label="Permalink to &quot;Line&quot;">​</a></h2><h2 id="rect" tabindex="-1">Rect <a class="header-anchor" href="#rect" aria-label="Permalink to &quot;Rect&quot;">​</a></h2><h3 id="per-rect-attributes" tabindex="-1">Per-rect attributes <a class="header-anchor" href="#per-rect-attributes" aria-label="Permalink to &quot;Per-rect attributes&quot;">​</a></h3><p>fill<br> border color<br> border size<br> x_min<br> x_max<br> y_min<br> y_max</p><h3 id="uniforms" tabindex="-1">Uniforms <a class="header-anchor" href="#uniforms" aria-label="Permalink to &quot;Uniforms&quot;">​</a></h3><p>...</p><h2 id="area-fill" tabindex="-1">Area Fill <a class="header-anchor" href="#area-fill" aria-label="Permalink to &quot;Area Fill&quot;">​</a></h2><p>..</p><h2 id="quad-bezier-stroke" tabindex="-1">Quad Bezier Stroke <a class="header-anchor" href="#quad-bezier-stroke" aria-label="Permalink to &quot;Quad Bezier Stroke&quot;">​</a></h2><p>..</p><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><p>The text shader is ported from the original Slug shader, with a modification to support COLRv1. CBDT is still not supported. CBDT is an old format using bitmaps.</p><p>If you are going to use color emojis, make sure the font file uses COLRv1, not CBDT.<br> For example, some distros ships <code>Noto Color Emojis</code> with COLRv1 while others ship CBDT.</p><h2 id="polar-area" tabindex="-1">Polar Area <a class="header-anchor" href="#polar-area" aria-label="Permalink to &quot;Polar Area&quot;">​</a></h2><p>..</p>`,32)])])}const u=a(s,[["render",o]]);export{m as __pageData,u as default};
